#pragma once

#include <cstdint>

// The walls of the world map that a bomb breaks open. The table is generated by tools/gen_walls.py.
namespace Data
{
    struct Wall
    {
        uint32_t hash; // CRC32 of its flag in the save, MainField_WallCrack_<hash id>, set once it is broken
        float x;
        float y;       // the game's z
    };

    extern const Wall Walls[]; // sorted by hash
    extern const int WallsCount;

    // Tag of the map objects drawn for the walls.
    struct WallIcon {};
}
